(function () {
/**
 * 拼多多 · 「指定类目 × 全品牌库」强制假一赔十全库扫描器
 * ------------------------------------------------------------------
 * 用途：给定一个末级类目，在**整个品牌库**上扫描出所有强制假一赔十的品牌。
 *
 * 设计要点（针对平台限流）：
 *   - 平台会返回两种限流码：55555 / 40002（"操作太过频繁"），两者都必须退避重试
 *   - 并发必须低（默认 3）；实测并发 12 会在几十秒内把额度打满
 *   - 失败 vid 会进入 failed 队列，主流程结束后自动多轮补扫
 *   - 全程状态挂在 window.__arkScanX，可随时读取进度、可断点查看
 *
 * 用法（在已登录的发布页控制台）：
 *   await runFullBrandScan(5908)                       // 默认并发 3
 *   await runFullBrandScan(5908, { conc: 2, download: true })
 *   arkScanStatus()                                    // 查看进度
 *   arkScanExport(5908)                                // 导出已扫出的强制品牌 CSV
 *
 * 依赖：先跑过品牌库枚举（window.__big.map: {vid: name}）。
 *       若没有，可先用 seed 扫描建立；或直接传入 vids 列表。
 */

const ARK_REF_PID = 310;

function arkSleep(ms) { return new Promise(r => setTimeout(r, ms)); }

/** 单次规则判定（含双限流码退避） */
async function arkRuleQuery(catId, vid, bucket) {
  for (let a = 0; a < 6; a++) {
    try {
      const r = await fetch('/glide/v2/mms/query/rules/limit/new', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ cat_id: catId, goods_type: 1, goods_properties: [{ ref_pid: ARK_REF_PID, vid: vid }] })
      });
      const j = await r.json();
      if (j && j.success) {
        return { must: j.result.is_must_fake_one_lose_ten === true, notShow: j.result.is_not_show_fake_one_lose_ten === true };
      }
      const code = String(j && (j.error_code || j.errorCode));
      if (code === '55555' || code === '40002') { bucket.throttled++; await arkSleep(1200 * (a + 1)); continue; }
      return { other: code };
    } catch (e) { await arkSleep(800 * (a + 1)); }
  }
  return null; // 彻底失败 → 进 failed 队列
}

/** 全库扫描主函数 */
async function runFullBrandScan(catId, opts) {
  opts = opts || {};
  const map = (window.__big && window.__big.map) || {};
  let vids = opts.vids || Object.keys(map).map(Number).sort((a, b) => a - b);
  if (!vids.length) throw new Error('没有候选 vid：请先跑品牌库枚举，或用 opts.vids 传入');

  const S = window.__arkScanX = {
    catId: catId, total: vids.length, conc: opts.conc || 3,
    tested: 0, ok: 0, failed: [], must: [], notShow: [],
    throttled: 0, rounds: 0, killed: false, done: false, started: Date.now()
  };

  const run = async (list) => {
    let i = 0;
    const worker = async () => {
      while (i < list.length && !S.killed) {
        const v = list[i++];
        const r = await arkRuleQuery(catId, v, S);
        S.tested++;
        if (r === null) S.failed.push(v);
        else { S.ok++; if (r.must) S.must.push(v); if (r.notShow) S.notShow.push(v); }
      }
    };
    await Promise.all(Array.from({ length: S.conc }, worker));
  };

  await run(vids);
  while (S.failed.length && S.rounds < 6 && !S.killed) {
    const retry = S.failed.splice(0);
    S.rounds++;
    await arkSleep(3000);
    await run(retry);
  }
  S.done = true;
  S.finishedAt = Date.now();
  if (opts.download) arkScanExport(catId);
  return S;
}

/** 进度 */
function arkScanStatus() {
  const S = window.__arkScanX;
  if (!S) return 'no scan';
  const pct = Math.round(S.tested / S.total * 1000) / 10;
  const mins = (Date.now() - S.started) / 60000;
  const rate = S.tested / Math.max(mins, 0.1);
  return { catId: S.catId, done: S.done, tested: S.tested, total: S.total, ok: S.ok, pct: pct + '%', must: S.must.length, pendingFailed: S.failed.length, throttled: S.throttled, rounds: S.rounds, ratePerMin: Math.round(rate), etaMin: rate > 0 ? Math.round((S.total - S.tested) / rate) : null };
}

/** 导出已扫出的强制品牌（含名称与 vid） */
function arkScanExport(catId, filename) {
  const S = window.__arkScanX;
  if (!S) return null;
  const map = (window.__big && window.__big.map) || {};
  const rows = S.must.map(v => [catId, v, map[v] === undefined ? '' : map[v]]);
  arkDownloadCsv(filename || ('强制假一赔十_全库_' + catId + '.csv'), rows);
  return { catId: catId, forced: rows.length, scanned: S.tested, ofTotal: S.total };
}

/** CSV 下载 */
function arkDownloadCsv(filename, rows, header) {
  header = header || ['cat_id', 'brand_vid', 'brand_name'];
  const q = s => '"' + String(s === undefined || s === null ? '' : s).replace(/"/g, '""') + '"';
  const csv = '\uFEFF' + [header.map(q).join(',')].concat(rows.map(r => r.map(q).join(','))).join('\r\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 3000);
}

